mapper.select:
SELECT COALESCE(i.RESULT_MASTER_RECORD_ID, i.MASTER_RECORD_ID) AS RECORD_ID, r.ID AS REQUEST_ID, r.REQUEST_NO FROM MASTER_CHANGE_REQUEST_ITEM i INNER JOIN MASTER_CHANGE_REQUEST r ON r.ID = i.REQUEST_ID WHERE r.MODEL_ID = #{modelId} AND (r.STATUS = '0' OR (r.STATUS = '1' AND r.EXECUTE_STATUS IN ('0', '1'))) AND r.SUBMIT_TIME IS NOT NULL AND r.VALID_FLAG = '1' AND r.DEL_FLAG = '0' AND i.VALID_FLAG = '1' AND i.DEL_FLAG = '0' AND COALESCE(i.RESULT_MASTER_RECORD_ID, i.MASTER_RECORD_ID) IN
#{recordId}
ORDER BY r.ID, i.ITEM_NO, i.ID

SELECT MODEL_ID, COUNT(1) AS PENDING_COUNT FROM MASTER_CHANGE_REQUEST WHERE CHANGE_SOURCE = 'MANUAL' AND STATUS = '0' AND SUBMIT_TIME IS NOT NULL AND VALID_FLAG = '1' AND DEL_FLAG = '0' AND MODEL_ID IN
#{modelId}
GROUP BY MODEL_ID

mapper.sql:
WHERE r.APPLICANT_ID = #{query.applicantId}
  AND r.CHANGE_SOURCE IN ('MANUAL', 'MERGE')
  AND r.SUBMIT_TIME IS NOT NULL
  AND r.VALID_FLAG = '1'
  AND r.DEL_FLAG = '0'

    AND r.APPLICANT_ID = #{query.selectedApplicantId}



        AND r.CHANGE_TYPE = 'CREATE'


        AND r.CHANGE_TYPE = #{query.changeType}



    AND LOWER(r.REQUEST_NO) LIKE #{query.requestNoLike} ESCAPE '!'


    AND LOWER(r.REQUEST_NAME) LIKE #{query.targetNameLike} ESCAPE '!'


    AND EXISTS (SELECT 1 FROM system_user u
        WHERE u.user_id = r.APPLICANT_ID
          AND LOWER(u.nick_name) LIKE #{query.applicantNameLike} ESCAPE '!')


    AND EXISTS (SELECT 1 FROM MODEL_BASE m WHERE m.ID = r.MODEL_ID
        AND m.PROJECT_ID = #{query.projectId}

            AND m.LAYER_ID IN
            #{layerId}

    )


    AND r.MODEL_ID = #{query.modelId}


    AND r.STATUS = #{query.approvalStatus}


    AND (LOWER(r.REQUEST_NO) LIKE #{query.keywordLike} ESCAPE '!'
      OR LOWER(r.REQUEST_NAME) LIKE #{query.keywordLike} ESCAPE '!'

          OR r.MODEL_ID IN

              #{modelId}


    )
